using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SRECommerce.BuildingBlocks.Contracts;using SRECommerce.BuildingBlocks.Infrastructure;using SRECommerce.Order.Domain;
namespace SRECommerce.Order.Infrastructure;
public sealed class OrderDbContext(DbContextOptions<OrderDbContext> options,ModuleScope scope):DbContext(options),IModuleStore
{
 public Guid? CurrentTenant=>scope.TenantId;public DbContext Context=>this;public DbSet<OutboxMessage> Outbox=>Set<OutboxMessage>();public DbSet<InboxMessage> Inbox=>Set<InboxMessage>();public DbSet<AuditEntry> Audit=>Set<AuditEntry>();
 public DbSet<CheckoutIntent> Intents=>Set<CheckoutIntent>();public DbSet<SalesOrder> Orders=>Set<SalesOrder>();public DbSet<OrderItem> Items=>Set<OrderItem>();public DbSet<OrderReservation> Reservations=>Set<OrderReservation>();public DbSet<OrderStatusHistory> History=>Set<OrderStatusHistory>();public DbSet<OrderOperation> Operations=>Set<OrderOperation>();public DbSet<OrderFulfillment> Fulfillments=>Set<OrderFulfillment>();public DbSet<OrderReturn> Returns=>Set<OrderReturn>();public DbSet<OrderExchange> Exchanges=>Set<OrderExchange>();public DbSet<OrderImport> Imports=>Set<OrderImport>();public DbSet<OrderPolicy> Policies=>Set<OrderPolicy>();
 protected override void OnModelCreating(ModelBuilder model)
 {
  model.ConfigureInfrastructure();model.Entity<OutboxMessage>().TenantEntity(x=>x.TenantId==CurrentTenant);model.Entity<InboxMessage>().TenantEntity(x=>x.TenantId==CurrentTenant);model.Entity<AuditEntry>().TenantEntity(x=>x.TenantId==CurrentTenant);
  void Tenant<T>(string table,Action<EntityTypeBuilder<T>>? configure=null)where T:class,SRECommerce.BuildingBlocks.Kernel.ITenantRecord
  {var e=model.Entity<T>();e.ToTable(table);e.HasKey("TenantId","Id");e.TenantEntity(x=>x.TenantId==CurrentTenant);configure?.Invoke(e);}
  Tenant<OrderPolicy>("OrderPolicies",e=>{e.HasIndex(x=>x.TenantId).IsUnique();e.ToTable(t=>{t.HasCheckConstraint("CK_OrderPolicies_Returns","[ReturnWindowDays] BETWEEN 0 AND 365");t.HasCheckConstraint("CK_OrderPolicies_Maximum","[MaximumTotal]>0");});});
  Tenant<CheckoutIntent>("CheckoutIntents",e=>{e.Property(x=>x.CustomerRole).HasMaxLength(30);e.Property(x=>x.GuestKeyHash).HasMaxLength(32).IsFixedLength();e.Property(x=>x.RequestHash).HasMaxLength(64);e.Property(x=>x.RequestDocument).HasMaxLength(10000);e.Property(x=>x.CartClaimDocument).HasMaxLength(131072);e.Property(x=>x.LastFault).HasMaxLength(80);e.Property(x=>x.CancellationReason).HasMaxLength(300);e.HasIndex(x=>new{x.State,x.NextAttemptAt,x.LeaseUntil});e.ToTable(t=>{t.HasCheckConstraint("CK_CheckoutIntents_Request","ISJSON([RequestDocument])=1");t.HasCheckConstraint("CK_CheckoutIntents_Claim","ISJSON([CartClaimDocument])=1");t.HasCheckConstraint("CK_CheckoutIntents_Attempts","[Attempts]>=0");});});
  Tenant<SalesOrder>("Orders",e=>{e.Property(x=>x.Number).HasMaxLength(80);e.Property(x=>x.PaymentMethod).HasMaxLength(20);e.Property(x=>x.Currency).HasMaxLength(3);e.Property(x=>x.ContactDocument).HasMaxLength(4000);e.Property(x=>x.PriceSnapshot).HasMaxLength(131072);e.Property(x=>x.ShippingSnapshot).HasMaxLength(65536);e.Property(x=>x.InvoiceReference).HasMaxLength(80);e.Property(x=>x.SourceReference).HasMaxLength(120);e.HasIndex(x=>new{x.TenantId,x.Number}).IsUnique();e.HasIndex(x=>new{x.TenantId,x.CartId,x.CartRevision}).IsUnique().HasFilter("[CartId] IS NOT NULL");e.HasIndex(x=>new{x.TenantId,x.InvoiceReference}).IsUnique().HasFilter("[InvoiceReference] IS NOT NULL");e.HasIndex(x=>new{x.TenantId,x.SourceReference}).IsUnique().HasFilter("[SourceReference] IS NOT NULL");e.HasIndex(x=>new{x.TenantId,x.UserId,x.CreatedAt});e.HasIndex(x=>new{x.TenantId,x.Status,x.CreatedAt});e.ToTable(t=>{t.HasCheckConstraint("CK_Orders_Totals","[Subtotal]>=0 AND [Discount]>=0 AND [Net]>=0 AND [Tax]>=0 AND [ShippingTotal]>=0 AND [ItemsTotal]=[Net]+[Tax] AND [Total]=[ItemsTotal]+[ShippingTotal] AND [Refunded]>=0 AND [Refunded]<=[Total]");t.HasCheckConstraint("CK_Orders_Precision","[DecimalPlaces] BETWEEN 0 AND 3");t.HasCheckConstraint("CK_Orders_Documents","ISJSON([ContactDocument])=1 AND ISJSON([PriceSnapshot])=1 AND ISJSON([ShippingSnapshot])=1");});});
  model.Entity<OrderItem>(e=>{e.ToTable("OrderItems",t=>t.HasCheckConstraint("CK_OrderItems_Quantities","[Quantity]>0 AND [ShipmentRequested]>=0 AND [ShipmentRequested]<=[Quantity] AND [Fulfilled]>=0 AND [Fulfilled]<=[ShipmentRequested] AND [Delivered]>=0 AND [Delivered]<=[Fulfilled] AND [ReturnRequested]>=0 AND [ReturnRequested]<=[Delivered] AND [Returned]>=0 AND [Returned]<=[ReturnRequested] AND [RefundAllocated]>=0 AND [RefundAllocated]<=[Total]"));e.HasKey(x=>new{x.TenantId,x.OrderId,x.VariantId});e.Property(x=>x.Sku).HasMaxLength(64);e.Property(x=>x.Name).HasMaxLength(160);e.HasOne<SalesOrder>().WithMany(x=>x.Items).HasForeignKey(x=>new{x.TenantId,Id=x.OrderId}).OnDelete(DeleteBehavior.Restrict);e.TenantEntity(x=>x.TenantId==CurrentTenant);});
  Tenant<OrderReservation>("OrderReservations",e=>{e.Property(x=>x.Items).HasMaxLength(10000);e.Property(x=>x.RemoteVersion).HasMaxLength(30);e.HasIndex(x=>new{x.TenantId,x.OrderId,x.WarehouseId}).IsUnique();e.HasOne<SalesOrder>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.OrderId}).OnDelete(DeleteBehavior.Restrict);e.ToTable(t=>t.HasCheckConstraint("CK_OrderReservations_Items","ISJSON([Items])=1"));});
  Tenant<OrderStatusHistory>("OrderStatusHistory",e=>{e.Property(x=>x.Reason).HasMaxLength(300);e.HasIndex(x=>new{x.TenantId,x.OrderId,x.CreatedAt});e.HasOne<SalesOrder>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.OrderId}).OnDelete(DeleteBehavior.Restrict);});
  Tenant<OrderOperation>("OrderOperations",e=>{e.Property(x=>x.Hash).HasMaxLength(64);e.Property(x=>x.Action).HasMaxLength(80);e.Property(x=>x.Result).HasMaxLength(131072);e.HasOne<SalesOrder>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.OrderId}).OnDelete(DeleteBehavior.Restrict);e.ToTable(t=>t.HasCheckConstraint("CK_OrderOperations_Result","ISJSON([Result])=1"));});
  Tenant<OrderFulfillment>("OrderFulfillments",e=>{e.Property(x=>x.Items).HasMaxLength(10000);e.Property(x=>x.CourierReference).HasMaxLength(160);e.Property(x=>x.LastFault).HasMaxLength(80);e.HasIndex(x=>new{x.Status,x.CreatedAt});e.HasOne<SalesOrder>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.OrderId}).OnDelete(DeleteBehavior.Restrict);e.ToTable(t=>t.HasCheckConstraint("CK_OrderFulfillments_Items","ISJSON([Items])=1"));});
  Tenant<OrderReturn>("OrderReturns",e=>{e.Property(x=>x.Items).HasMaxLength(16000);e.Property(x=>x.Reason).HasMaxLength(300);e.Property(x=>x.LastFault).HasMaxLength(80);e.HasIndex(x=>new{x.Status,x.CreatedAt});e.HasOne<SalesOrder>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.OrderId}).OnDelete(DeleteBehavior.Restrict);e.ToTable(t=>{t.HasCheckConstraint("CK_OrderReturns_Items","ISJSON([Items])=1");t.HasCheckConstraint("CK_OrderReturns_Refund","[RefundAmount]>=0");});});
  Tenant<OrderExchange>("OrderExchanges",e=>{e.HasIndex(x=>new{x.TenantId,x.ReturnId}).IsUnique();e.HasOne<SalesOrder>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.OrderId}).OnDelete(DeleteBehavior.Restrict);e.HasOne<OrderReturn>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.ReturnId}).OnDelete(DeleteBehavior.Restrict);e.HasOne<SalesOrder>().WithMany().HasForeignKey(x=>new{x.TenantId,Id=x.ReplacementOrderId}).OnDelete(DeleteBehavior.Restrict);});
  Tenant<OrderImport>("OrderImports",e=>{e.Property(x=>x.Source).HasMaxLength(80);e.Property(x=>x.Hash).HasMaxLength(64);e.Property(x=>x.Result).HasMaxLength(5000);});
  foreach(var type in model.Model.GetEntityTypes().Where(t=>t.ClrType.Namespace=="SRECommerce.Order.Domain"))
  foreach(var property in type.GetProperties())
  {if(property.ClrType==typeof(decimal)){property.SetPrecision(18);property.SetScale(property.Name is "Quantity" or "ShipmentRequested" or "Fulfilled" or "Delivered" or "ReturnRequested" or "Returned"?3:4);}if(property.Name=="Version")model.Entity(type.ClrType).Property(property.Name).IsRowVersion();}
 }
 private void Guard()
 {
  this.GuardWrites(scope);
  if(ChangeTracker.Entries().Any(e=>e.Entity is OrderStatusHistory or OrderOperation or OrderImport&&e.State is EntityState.Modified or EntityState.Deleted))throw new BusinessFault("OrderHistoryImmutable",403);
  // Checkout financial and customer snapshots are permanent. Workflow fields may advance independently.
  string[] orderWorkflow=[nameof(SalesOrder.Status),nameof(SalesOrder.PaymentState),nameof(SalesOrder.Refunded),nameof(SalesOrder.DeliveredAt),nameof(SalesOrder.UpdatedAt),nameof(SalesOrder.Revision),nameof(SalesOrder.InvoiceReference)];
  string[] itemWorkflow=[nameof(OrderItem.ShipmentRequested),nameof(OrderItem.Fulfilled),nameof(OrderItem.Delivered),nameof(OrderItem.ReturnRequested),nameof(OrderItem.Returned),nameof(OrderItem.RefundAllocated)];
  foreach(var entry in ChangeTracker.Entries<SalesOrder>())
  {
   if(entry.State==EntityState.Deleted||entry.State==EntityState.Modified&&(entry.OriginalValues.GetValue<bool>(nameof(SalesOrder.Historical))||entry.Properties.Any(p=>p.IsModified&&!orderWorkflow.Contains(p.Metadata.Name))))throw new BusinessFault("OrderSnapshotImmutable",403);
   var originalInvoice=entry.OriginalValues.GetValue<string?>(nameof(SalesOrder.InvoiceReference));
   if(entry.State==EntityState.Modified&&originalInvoice is not null&&entry.Entity.InvoiceReference!=originalInvoice)throw new BusinessFault("InvoiceReferenceImmutable",403);
  }
  foreach(var entry in ChangeTracker.Entries<OrderItem>())
   if(entry.State==EntityState.Deleted||entry.State==EntityState.Modified&&entry.Properties.Any(p=>p.IsModified&&!itemWorkflow.Contains(p.Metadata.Name)))throw new BusinessFault("OrderSnapshotImmutable",403);
 }
 public override int SaveChanges(bool accept){Guard();return base.SaveChanges(accept);}public override Task<int> SaveChangesAsync(bool accept,CancellationToken ct=default){Guard();return base.SaveChangesAsync(accept,ct);}
}
